import { ask_for_freight } from '$lib/Versies/Trucks'	

export const request_ledger_info = async () => {
	const net_path = ask_for_freight ().dapp_network.net_path;
	
	
	const controller = new AbortController ();
	const { signal } = controller;
	const timeoutId = setTimeout(() => {
		controller.abort (); // Abort the fetch request
	}, 1000);
	
	const response = await fetch (net_path, {
		headers: {
			"Authorization": ask_for_freight ().dapp_network.Authorization,
		},
		signal
	});
	if (!response.ok) {
		throw new Error ('request_ledger_info failed');
    }
	const data = await response.json ();
	
	return {
		enhanced: data,
		status: response.status
	};
}