import { ask_for_freight } from '$lib/Versies/Trucks'	
	
export const view_fonction = async ({ 
	body,
	net_path = "",
	timeout_after_milliseconds = false
}) => {
	if (net_path.length === 0) {
		net_path = ask_for_freight ().dapp_network.net_path;
	}
	
	if (typeof timeout_after_milliseconds === "number") {
		const controller = new AbortController ();
		const { signal } = controller;
		const timeoutId = setTimeout(() => {
			controller.abort (); // Abort the fetch request
		}, timeout_after_milliseconds);
	}
	
	const proceeds = await fetch (`${ net_path }/view`, {
		method: "POST",
		headers: {
			"Authorization": ask_for_freight ().dapp_network.Authorization,
			"Content-Type": "application/json"
		},
		body: JSON.stringify (body)
	});	
	if (!proceeds.ok) {
		throw new Error ('view failed');
    }
	
	const result = await proceeds.json ()
	
	return { 
		result,
		result_string: JSON.stringify (result)
	};
}